\ir assert_isolated.sql
BEGIN;
CREATE FUNCTION pg_temp.check_it(value boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'OPERATIONS FAILED: %',label; END IF; END $$;
GRANT EXECUTE ON FUNCTION pg_temp.check_it(boolean,text) TO authenticated,anon;
DO $$ DECLARE uid uuid; label text; BEGIN
 FOREACH label IN ARRAY ARRAY['owner','other','student','account','admin'] LOOP
  uid:=gen_random_uuid();INSERT INTO auth.users(id,aud,role,is_anonymous,email,email_confirmed_at) VALUES(uid,'authenticated','authenticated',label NOT IN ('account','admin'),CASE WHEN label IN ('account','admin') THEN uid||'@example.invalid' ELSE NULL END,CASE WHEN label IN ('account','admin') THEN now() ELSE NULL END);
  PERFORM set_config('ops.'||label,uid::text,true);
 END LOOP;
 INSERT INTO auth.identities(provider_id,user_id,identity_data,provider) SELECT id::text,id,jsonb_build_object('sub',id::text,'email',email),'google' FROM auth.users WHERE id IN (current_setting('ops.account')::uuid,current_setting('ops.admin')::uuid);
 INSERT INTO physical_internal.teacher_access(user_id,expires_at) VALUES(current_setting('ops.owner')::uuid,now()+interval '2 hours'),(current_setting('ops.other')::uuid,now()+interval '2 hours'),(current_setting('ops.admin')::uuid,now()+interval '2 hours');
 INSERT INTO physical_internal.teacher_accounts(user_id,role,enabled) VALUES(current_setting('ops.admin')::uuid,'admin',true);
END $$;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('ops.owner'),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
SELECT set_config('ops.room',public.create_secure_classroom('Operations fixture',NULL,ARRAY['1모둠'])->>'id',true);
SELECT pg_temp.check_it((public.classroom_operations(current_setting('ops.room')::uuid,'status')->>'reviewScores')::boolean,'new room requires review');
UPDATE public.game_rooms SET status='playing' WHERE id=current_setting('ops.room')::uuid;
RESET ROLE;
SELECT set_config('ops.group',(SELECT id::text FROM public.room_groups WHERE room_id=current_setting('ops.room')::uuid),true);
INSERT INTO physical_internal.classroom_members(room_id,user_id,group_id,expires_at) VALUES(current_setting('ops.room')::uuid,current_setting('ops.student')::uuid,current_setting('ops.group')::uuid,now()+interval '4 hours');
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('ops.student'),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
DO $$ BEGIN BEGIN PERFORM public.increment_classroom_score(current_setting('ops.group')::uuid,100,'forged-direct');RAISE EXCEPTION 'direct student score accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
SELECT set_config('ops.request',public.submit_classroom_score(current_setting('ops.group')::uuid,200,'ops-action','reaction')->>'id',true);
SELECT pg_temp.check_it(public.submit_classroom_score(current_setting('ops.group')::uuid,200,'ops-action','reaction')->>'id'=current_setting('ops.request'),'retry reuses request');
SELECT pg_temp.check_it(public.submit_classroom_score(current_setting('ops.group')::uuid,400,'ops-new-action','reaction')->>'id'=current_setting('ops.request'),'pending repeated activity does not duplicate');
DO $$ BEGIN BEGIN PERFORM public.submit_classroom_score(current_setting('ops.group')::uuid,10001,'over-limit','reaction');RAISE EXCEPTION 'score exceeded limit';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;END $$;
DO $$ BEGIN BEGIN PERFORM public.delete_managed_classroom(current_setting('ops.room')::uuid,'Operations fixture');RAISE EXCEPTION 'student deleted room';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
RESET ROLE;
SELECT pg_temp.check_it((SELECT score=0 FROM public.room_groups WHERE id=current_setting('ops.group')::uuid),'pending score not applied');
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('ops.other'),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
DO $$ BEGIN BEGIN PERFORM public.review_classroom_score(current_setting('ops.room')::uuid);RAISE EXCEPTION 'other teacher read queue';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
DO $$ BEGIN BEGIN PERFORM public.delete_managed_classroom(current_setting('ops.room')::uuid,'Operations fixture');RAISE EXCEPTION 'other teacher deleted room';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
RESET ROLE;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('ops.owner'),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.check_it(public.review_classroom_score(current_setting('ops.room')::uuid,current_setting('ops.request')::uuid,150,true)->>'state'='approved','teacher approves edited score');
SELECT public.review_classroom_score(current_setting('ops.room')::uuid,current_setting('ops.request')::uuid,150,true);
DO $$ BEGIN BEGIN PERFORM public.delete_managed_classroom(current_setting('ops.room')::uuid,'wrong name');RAISE EXCEPTION 'wrong confirmation accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;END $$;
UPDATE public.game_rooms SET status='finished' WHERE id=current_setting('ops.room')::uuid;
RESET ROLE;
SELECT pg_temp.check_it((SELECT score=150 FROM public.room_groups WHERE id=current_setting('ops.group')::uuid),'approval retry increments only once');
SELECT pg_temp.check_it((SELECT finished_at IS NOT NULL AND retention_started_at IS NOT NULL FROM public.game_rooms WHERE id=current_setting('ops.room')::uuid),'finish stamps retention');
-- Simulate elapsed time only in this rolled-back test room.
ALTER TABLE public.game_rooms DISABLE TRIGGER stamp_classroom_finished;
UPDATE public.game_rooms SET finished_at=now()-interval '8 days',retention_started_at=now()-interval '8 days' WHERE id=current_setting('ops.room')::uuid;
ALTER TABLE public.game_rooms ENABLE TRIGGER stamp_classroom_finished;
UPDATE physical_internal.classroom_members SET expires_at=now()-interval '1 hour' WHERE room_id=current_setting('ops.room')::uuid;
SELECT pg_temp.check_it((physical_internal.cleanup_classrooms(true)->>'rooms')::integer>=1,'retention preview finds elapsed room');
SELECT physical_internal.cleanup_classrooms(false);
SELECT pg_temp.check_it(NOT EXISTS(SELECT 1 FROM public.game_rooms WHERE id=current_setting('ops.room')::uuid),'elapsed room removed');
SELECT pg_temp.check_it(NOT EXISTS(SELECT 1 FROM physical_internal.student_score_requests WHERE room_id=current_setting('ops.room')::uuid),'score queue cascades');

SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('ops.account'),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.check_it((public.teacher_account()->>'enabled')::boolean=true,'verified Google member joins without approval');
RESET ROLE;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('ops.admin'),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
SELECT public.manage_teacher_account(current_setting('ops.account')::uuid,true,'teacher');
DO $$ BEGIN BEGIN PERFORM public.manage_teacher_account(current_setting('ops.admin')::uuid,false,'teacher');RAISE EXCEPTION 'last administrator disabled';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;END $$;
RESET ROLE;
SELECT pg_temp.check_it((SELECT enabled AND version=2 FROM physical_internal.teacher_accounts WHERE user_id=current_setting('ops.account')::uuid),'admin approval changes session version');
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('ops.admin'),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
SELECT public.manage_teacher_account(current_setting('ops.account')::uuid,false,'teacher');
RESET ROLE;
SELECT pg_temp.check_it((SELECT NOT enabled AND blocked AND version=3 FROM physical_internal.teacher_accounts WHERE user_id=current_setting('ops.account')::uuid),'account revoke effective');
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('ops.account'),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.check_it((public.teacher_account()->>'enabled')::boolean=false,'Google re-login cannot unblock a restricted account');
DO $$ BEGIN BEGIN PERFORM public.teacher_members();RAISE EXCEPTION 'ordinary member saw other members';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
RESET ROLE;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('ops.admin'),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.check_it(jsonb_array_length(public.teacher_members(0,1,'')->'members')=1,'administrator can page member list');
SELECT pg_temp.check_it((public.teacher_members(0,30,'definitely-not-a-member-query')->>'total')::integer=0,'member search is scoped and literal');
RESET ROLE;
-- Neither a pupil nor another teacher can delete a legacy unowned room.
INSERT INTO public.game_rooms(id,name,pin_code,status,teacher_id) VALUES(gen_random_uuid(),'Unowned operations fixture','O'||substr(gen_random_uuid()::text,1,7),'locked',NULL) RETURNING set_config('ops.legacy',id::text,true);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('ops.other'),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
DO $$ BEGIN BEGIN PERFORM public.delete_managed_classroom(current_setting('ops.legacy')::uuid,'Unowned operations fixture');RAISE EXCEPTION 'other teacher deleted unowned room';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
DO $$ BEGIN BEGIN PERFORM public.activity_review_records('reaction',repeat('a',64),true,true,true);RAISE EXCEPTION 'teacher published admin review';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
RESET ROLE;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('ops.admin'),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.check_it(public.delete_managed_classroom(current_setting('ops.legacy')::uuid,'Unowned operations fixture'),'administrator explicitly deletes legacy room');
SELECT public.activity_review_records('reaction',repeat('a',64),true,true,false);
RESET ROLE;
SET LOCAL ROLE anon;
SELECT pg_temp.check_it(jsonb_array_length(public.activity_review_records())>=1,'public review has no identities');
DO $$ BEGIN BEGIN PERFORM public.manage_teacher_account();RAISE EXCEPTION 'anonymous account list';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
DO $$ BEGIN BEGIN PERFORM public.teacher_login_attempt('wrong-secret',repeat('b',64));RAISE EXCEPTION 'bad server secret';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
RESET ROLE;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('ops.admin'),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.check_it(public.teacher_login_policy(false)=false,'administrator ends shared-code access');
RESET ROLE;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('ops.owner'),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.check_it(NOT physical_internal.is_classroom_teacher(),'old shared-code database grant revoked');
RESET ROLE;
ROLLBACK;
